```cpp
#include <iostream>
#include <fstream>
#include <string>
using namespace std;

int main() {
    ifstream plik("kody.txt");
    int n;
    int ileA = 0, ileB = 0, ileC = 0;
    string listaA, listaB, listaC;

    while (plik >> n) {
        int c[4];
        c[0] = n / 1000;
        c[1] = (n / 100) % 10;
        c[2] = (n / 10) % 10;
        c[3] = n % 10;

        // a) pierwsza == ostatnia
        if (c[0] == c[3]) {
            ileA++;
            if (!listaA.empty()) listaA += ", ";
            listaA += to_string(n);
        }

        // b) wszystkie rozne
        bool rozne = true;
        bool uzyto[10] = {false};
        for (int i = 0; i < 4; i++) {
            if (uzyto[c[i]]) { rozne = false; break; }
            uzyto[c[i]] = true;
        }
        if (rozne) {
            ileB++;
            if (!listaB.empty()) listaB += ", ";
            listaB += to_string(n);
        }

        // c) niemalejaco
        if (c[0] <= c[1] && c[1] <= c[2] && c[2] <= c[3]) {
            ileC++;
            if (!listaC.empty()) listaC += ", ";
            listaC += to_string(n);
        }
    }

    cout << "a) Pierwsza = ostatnia: " << ileA << endl;
    cout << "   (" << listaA << ")" << endl;
    cout << "b) Wszystkie cyfry rozne: " << ileB << endl;
    cout << "   (" << listaB << ")" << endl;
    cout << "c) Cyfry niemalejaco: " << ileC << endl;
    cout << "   (" << listaC << ")" << endl;
    return 0;
}
```

**Wyjasnienie**: Wyodrebniamy 4 cyfry za pomoca dzielenia calkowitego i modulo. (a) Porownanie pierwszej i ostatniej. (b) Tablica bool[10] do sprawdzenia unikalnosci. (c) Ciag porownan <=.

